{"policy":"permit (
    principal is User,
    action == Action::"cloneRepository",
    resource is Repository
)
when {
    principal.roles.contains(Role::"developer") &&
    principal.clearanceLevel == ClearanceLevel::"confidential" &&
    resource.sensitivityClassification == ClearanceLevel::"confidential" &&
    resource.topicTags.contains("regulated-data") &&
    resource.lifecycleStatus == RepositoryLifecycleStatus::"active"
};

forbid (
    principal is User,
    action == Action::"cloneRepository",
    resource is Repository
)
when {
    principal.roles.containsAny([
        Role::"developer",
        Role::"reviewer",
        Role::"maintainer",
        Role::"securityLead"
    ]) &&
    resource.topicTags.contains("regulated-data") &&
    (
        (principal.clearanceLevel == ClearanceLevel::"public" &&
            resource.sensitivityClassification != ClearanceLevel::"public") ||
        (principal.clearanceLevel == ClearanceLevel::"internal" &&
            (resource.sensitivityClassification == ClearanceLevel::"confidential" ||
             resource.sensitivityClassification == ClearanceLevel::"restricted")) ||
        (principal.clearanceLevel == ClearanceLevel::"confidential" &&
            resource.sensitivityClassification == ClearanceLevel::"restricted")
    )
};

forbid (
    principal is User,
    action == Action::"cloneRepository",
    resource is Repository
)
when {
    !resource.topicTags.contains("regulated-data")
};

forbid (
    principal is User,
    action == Action::"cloneRepository",
    resource is Repository
)
when {
    resource.lifecycleStatus == RepositoryLifecycleStatus::"archived"
};"}
